import icontract
from typing import List
import bisect

@icontract.require(lambda lst: all(lst[i] <= lst[i+1] for i in range(len(lst)-1)))
@icontract.ensure(lambda lst, val, result: len(result) == len(lst) + 1)
@icontract.ensure(lambda val, result: val in result)
@icontract.ensure(lambda result: all(result[i] <= result[i+1] for i in range(len(result)-1)))
def sorted_insert(lst: List[int], val: int) -> List[int]:
    result = lst[:]
    bisect.insort(result, val)
    return result
